function getBroadcastAddress(ip, mask) {
    const isValid = str => str.split('.').every(n => n >= 0 && n <= 255);

    if (!isValid(ip) || !isValid(mask)) {
        throw new Error("IP ou masque invalide");
    }

    const ipParts = ip.split('.').map(Number);
    const maskParts = mask.split('.').map(Number);

    return ipParts.map((ipPart, i) =>
        (ipPart & maskParts[i]) | (~maskParts[i] & 255)
    ).join('.');
}

