let client = new bacnet.default({
    apduTimeout: 2000,
    broadcastAddress: flow.get('ipBroadcast'),
    port: 47808,
});

/* clear console*/
msg.payload = [];
node.send(msg);
client.on('error', (err) => {
    node.error('Erreur client: ' + err.message);
    client.close();
});

let address;

let objectType = flow.get('objectType');
switch (objectType) {
    case "ANALOG_VALUE":
        objectType = bacnet.ObjectType.ANALOG_VALUE;
        break;
    case "ANALOG_INPUT":
        objectType = bacnet.ObjectType.ANALOG_INPUT;
        break;
    case "ANALOG_OUTPUT":
        objectType = bacnet.ObjectType.ANALOG_OUTPUT;
        break;
    case "BINARY_VALUE":
        objectType = bacnet.ObjectType.BINARY_VALUE;
        break;
    case "BINARY_INPUT":
        objectType = bacnet.ObjectType.BINARY_INPUT;
        break;
    case "BINARY_OUTPUT":
        objectType = bacnet.ObjectType.BINARY_OUTPUT;
        break;
}

const targetInstances = flow.get('targetInstances');
const targetInstancesString = JSON.stringify(targetInstances, null, 2);
let targetInstancesArray = new Array();

let j = 0;
/*this is abominable, but it works*/
for (let i = 0; i < targetInstancesString.length; i++) {
    targetInstancesArray[i] = 0;
}
for (let i = 1; i < targetInstancesString.length - 1; i++) {
    if ((targetInstancesString[i]) === ',') {
        j++;
    } else {
        targetInstancesArray[j] *= 10;
        targetInstancesArray[j] += Number(targetInstancesString[i]);
    }
}

const serviceChoice = flow.get('serviceChoice');

let inputValue = flow.get('inputValue');

let bacnetValue;
if (typeof inputValue === "boolean") {
    bacnetValue = {
        type: bacnet.ApplicationTag.BOOLEAN,
        value: inputValue
    };
} else if (!isNaN(inputValue)) {
    bacnetValue = {
        type: bacnet.ApplicationTag.REAL,
        value: Number(inputValue)
    };
}

let results = [];
try {
    switch (serviceChoice) {
        /*READ*/
        case "serviceRead":
            address = {
                address: flow.get('ip') + ":" + flow.get('portDest'),
            };
            for (let i = 0; i <= j; i++) {
                const instance = targetInstancesArray[i];
                const value = await client.readProperty(
                    address, {
                        type: objectType,
                        instance: instance
                    },
                    bacnet.PropertyIdentifier.PRESENT_VALUE
                );
                let result = {
                    object: objectType,
                    instance: instance,
                    value: value.values[0].value
                };

                msg.payload = result;
                results.push(result);
                node.send(msg);
            }
            if(j > 0){
                msg.payload ={status : "✅ multiple read sucessful"} ;
            }
            else{
                msg.payload ={status :"✅ read sucessful"} ;
            }

            node.send(msg);

        break;
            /*WRITE*/
        case "serviceWrite":
            address = {
                address: flow.get('ip') + ":" + flow.get('portDest'),
            };
            if (j > 0) {
                /* multiple write */
                const requestArray = [];
                for (let i = 0; i <= j; i++) {
                    const instance = targetInstancesArray[i];
                    requestArray.push({
                        objectId: {
                            type: objectType,
                            instance: instance
                        },
                        values: [{
                            property: {
                                id: bacnet.PropertyIdentifier.PRESENT_VALUE
                            },
                            value: [{
                                type: bacnetValue.type,
                                value: bacnetValue.value
                            }],
                            priority: 8
                        }]
                    });
                }

                await client.writePropertyMultiple(
                    address,
                    requestArray
                );



                msg.payload = { status: "✅ multiple write sucessful"};
                node.send(msg);
            }
            /* single write*/
            else {

                const instance = targetInstancesArray[0];
                await client.writeProperty(
                    address, {
                        type: objectType,
                        instance: instance
                    },
                    bacnet.PropertyIdentifier.PRESENT_VALUE,
                    [{
                        type: bacnetValue.type,
                        value: bacnetValue.value
                    }], {
                        priority: 8
                    }
                );
                let result = {
                    object: objectType,
                    instance: instance,
                    writtenValue: inputValue
                };
                results.push(result);
                node.send(msg);
                msg.payload = { status: "✅ write sucessful" };
                node.send(msg);

            }

        break;
        /*WHOIS*/
        case "whoIs":
            const discoveryMs = 1000;
            results = [];

            const onIAm = (device) => {
                const sender = device.header.sender.address;
                const deviceId = device.payload.deviceId;

                results.push({
                    deviceId: deviceId,
                    address: sender
                });

                node.warn(`Am reçu: ${deviceId} address : ${sender}`);
            };

            client.on('iAm', onIAm);

            setTimeout(() => {
                client.whoIs({
                    address: flow.get('ipBroadcast')
                });
                node.warn("whoIs broadcast sent");
            }, 500);

            setTimeout(() => {
                client.removeListener('iAm', onIAm);
                msg.payload = results;
                node.send(msg);
                msg.payload = { status: "✅ who-is sucessful" };
                node.send(msg);
                client.close();
            }, discoveryMs);

            return;
    }
}
catch (err) {
    node.error("Erreur BACnet: " + err);
    msg.payload = {status : "❌" + err.message };
    return msg;
}
